head.script:
// windowContainer 창(wframe) 안에서 브라우저 팝업(browserPopup)을 열며 dataObject 로 값 전달
scwin.trigger2_onclick = function (e) {
	var dataObj = {
		type: "json",
		data: { "addr": "서울시", "name": "손예진", "rowStatus": "R" },
		name: "paramTest"
	};
	var opts = {
		"id": "popup_window",
		"type": "browserPopup",
		"width": "500px",
		"height": "300px",
		"top": 250,
		"left": 250,
		"popupName": "윈도우 팝업[window type]",
		"modal": false,
		"useModalStack": false,
		"useIFrame": false,
		"dataObject": dataObj,
		"resizable": false,
		"title": "focusTest",
		"frameMode": ""
	};
	$p.openPopup("/sample/common_link/windowContainer_createWindow_WEFF-585_(WSQ-3939)_sub2.xml", opts);
};
